// Shared test helpers.
#pragma once

#include <catch2/catch_test_macros.hpp>

#include <cstdlib>
#include <filesystem>
#include <optional>

namespace waffle::test {

// GGUF model for tests that need a real model:
// 1. WAFFLE_TEST_MODEL environment variable;
// 2. otherwise tests/data/tiny-llama.gguf (generated by scripts/make_tiny_model.py);
// 3. otherwise nullopt -> the test calls SKIP().
inline std::optional<std::filesystem::path> test_model_path() {
    if (const char* env = std::getenv("WAFFLE_TEST_MODEL"); env && *env) {
        std::filesystem::path p(env);
        if (std::filesystem::is_regular_file(p)) return p;
    }
    std::filesystem::path tiny = std::filesystem::path(WAFFLE_SOURCE_DIR) / "tests" / "data" / "tiny-llama.gguf";
    if (std::filesystem::is_regular_file(tiny)) return tiny;
    return std::nullopt;
}

// Temporary directory owned by the test, deleted on destruction.
struct TempDir {
    std::filesystem::path path;
    explicit TempDir(const char* name) {
        path = std::filesystem::temp_directory_path() / "waffle_tests" / name;
        std::filesystem::remove_all(path);
        std::filesystem::create_directories(path);
    }
    ~TempDir() {
        std::error_code ec;
        std::filesystem::remove_all(path, ec);
    }
};

} // namespace waffle::test

#define WAFFLE_REQUIRE_MODEL(var)                                                                                      \
    auto var##_opt = ::waffle::test::test_model_path();                                                                \
    if (!var##_opt) SKIP("No test model (WAFFLE_TEST_MODEL or tests/data/tiny-llama.gguf)");                           \
    const std::filesystem::path var = *var##_opt
